package com.eventpulse.repository;
import com.eventpulse.model.NotificationRecord; import java.util.*; import software.amazon.awssdk.enhanced.dynamodb.*; import software.amazon.awssdk.enhanced.dynamodb.model.*;
public class NotificationRepository { private final DynamoDbTable<NotificationRecord> table; public NotificationRepository(DynamoDbEnhancedClient db,String n){table=db.table(n,TableSchema.fromBean(NotificationRecord.class));} public NotificationRecord save(NotificationRecord r){table.putItem(r);return r;} public Optional<NotificationRecord> findById(String id){return Optional.ofNullable(table.getItem(Key.builder().partitionValue(id).build()));}
 /** Atomic claim: only a new item or a definitively failed prior attempt can be sent. */
 public boolean claim(NotificationRecord r){var expression=Expression.builder().expression("attribute_not_exists(notificationId) OR #status = :failed").putExpressionName("#status","status").putExpressionValue(":failed",software.amazon.awssdk.services.dynamodb.model.AttributeValue.builder().s("FAILED").build()).build();try{table.putItem(PutItemEnhancedRequest.builder(NotificationRecord.class).item(r).conditionExpression(expression).build());return true;}catch(software.amazon.awssdk.services.dynamodb.model.ConditionalCheckFailedException alreadyClaimed){return false;}}
 public List<NotificationRecord> forUser(String id,int limit){int bounded=Math.max(1,Math.min(limit,100));return table.index("userId-createdAt-index").query(QueryEnhancedRequest.builder().queryConditional(QueryConditional.keyEqualTo(Key.builder().partitionValue(id).build())).scanIndexForward(false).limit(bounded).build()).stream().flatMap(p->p.items().stream()).limit(bounded).toList();} }
